class Solution:
    def minimumFlips(self, root: Optional[TreeNode], result: bool) -> int:
        def dfs(node):
            v = node.val
            if not node.left and not node.right:
                return [v, 1 - v]
            if v == 5:
                c = dfs(node.left if node.left else node.right)
                return [c[1], c[0]]
            l, r = dfs(node.left), dfs(node.right)
            if v == 2:
                return [l[0] + r[0], min(l[1] + r[1], l[1] + r[0], l[0] + r[1])]
            if v == 3:
                return [min(l[0] + r[0], l[0] + r[1], l[1] + r[0]), l[1] + r[1]]
            return [min(l[1] + r[0], l[0] + r[1]), min(l[1] + r[1], l[0] + r[0])]
        return dfs(root)[1 if result else 0]

