class Solution {
public:
    array<long long,2> dfs(TreeNode* node) {
        int v = node->val;
        if (!node->left && !node->right) return {(long long)v, 1 - v};
        if (v == 5) {
            TreeNode* c = node->left ? node->left : node->right;
            auto r = dfs(c);
            return {r[1], r[0]};
        }
        auto l = dfs(node->left), rr = dfs(node->right);
        if (v == 2) return {l[0] + rr[0], min({l[1] + rr[1], l[1] + rr[0], l[0] + rr[1]})};
        if (v == 3) return {min({l[0] + rr[0], l[0] + rr[1], l[1] + rr[0]}), l[1] + rr[1]};
        return {min(l[1] + rr[0], l[0] + rr[1]), min(l[1] + rr[1], l[0] + rr[0])};
    }
    int minimumFlips(TreeNode* root, bool result) {
        return (int)dfs(root)[result ? 1 : 0];
    }
};

