class Solution {
    private long[] dfs(TreeNode node) {
        int v = node.val;
        if (node.left == null && node.right == null) return new long[]{v, 1 - v};
        if (v == 5) {
            TreeNode c = node.left != null ? node.left : node.right;
            long[] r = dfs(c);
            return new long[]{r[1], r[0]};
        }
        long[] l = dfs(node.left), r = dfs(node.right);
        if (v == 2) return new long[]{l[0] + r[0], Math.min(l[1] + r[1], Math.min(l[1] + r[0], l[0] + r[1]))};
        if (v == 3) return new long[]{Math.min(l[0] + r[0], Math.min(l[0] + r[1], l[1] + r[0])), l[1] + r[1]};
        return new long[]{Math.min(l[1] + r[0], l[0] + r[1]), Math.min(l[1] + r[1], l[0] + r[0])};
    }
    public int minimumFlips(TreeNode root, boolean result) {
        return (int) dfs(root)[result ? 1 : 0];
    }
}

