        if (v === 3) return [Math.min(l[0] + r[0], l[0] + r[1], l[1] + r[0]), l[1] + r[1]];
        return [Math.min(l[1] + r[0], l[0] + r[1]), Math.min(l[1] + r[1], l[0] + r[0])];
    }
    return dfs(root)[result ? 1 : 0];
